using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using KingmakerMountedCombat.Diagnostics;
namespace KingmakerMountedCombat.Tests{
internal static class AssistedColdAuthorityTests{
 static int Main(){var t=new TestRunner();
 t.Run("sixth-Horse Manual308 grants one native load and no save or delete",()=>{var f=new F(sixthHorse:true);var a=f.Scope();TestRunner.True(a.MatchesAssistedColdInventoryPlan(f.R,f.Game,f.Manager),"Sixth-Horse plan mismatch.");TestRunner.Equal(0,a.AssistedColdWritableEntries,"Sixth-Horse gained writable entry.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)==null,"Sixth-Horse native load refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)!=null,"Sixth-Horse second load admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Target,f.Root)!=null,"Sixth-Horse write admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Delete,f.Target,f.Root)!=null,"Sixth-Horse delete admitted.");Counts(a,1);});
 foreach(var kind in new[]{"writable","write-cap","second-entry","wrong-load-cap","foreign-area","wrong-hash"})t.Run("sixth-Horse authority refuses "+kind,()=>{var f=new F(sixthHorse:true);Refuse(()=>f.Scope(true,kind));});
 t.Run("native roster departure grants no native save or second load",()=>{var f=new F(departure:true);var a=f.Scope();TestRunner.True(a.MatchesAssistedColdInventoryPlan(f.R,f.Game,f.Manager),"Departure plan mismatch.");TestRunner.Equal(0,a.AssistedColdWritableEntries,"Departure gained a writable entry.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)==null,"Departure native load refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)!=null,"Departure second load admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Target,f.Root)!=null,"Departure write admitted.");Counts(a,1);});
 t.Run("owner seed one read-only entry, one load, no write",()=>{var f=new F(true);var a=f.Scope();TestRunner.True(a.MatchesAssistedColdInventoryPlan(f.R,f.Game,f.Manager),"Seed plan mismatch.");TestRunner.Equal(1,a.AssistedColdEntryCount,"Entry count.");TestRunner.Equal(0,a.AssistedColdWritableEntries,"Writable entry.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Target,f.Root)!=null,"Seed write admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)==null,"Seed load refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)!=null,"Second seed load admitted.");Counts(a,1);});
 foreach(var kind in new[]{"writable","write-cap","second-entry"})t.Run("owner seed authority refuses "+kind,()=>{var f=new F(true);Refuse(()=>f.Scope(true,kind));});
 t.Run("owner seed captured selection mutation refuses the plan",()=>{var f=new F(true);var a=f.Scope();f.R.AssistedColdInventory.SeedId="OTHER_SEED";TestRunner.True(!a.MatchesAssistedColdInventoryPlan(f.R,f.Game,f.Manager),"Mutated seed plan admitted.");});
 t.Run("exact read-only Manual plan",()=>{var f=new F();var a=f.Scope();TestRunner.True(a.MatchesAssistedColdInventoryPlan(f.R,f.Game,f.Manager),"Plan mismatch.");TestRunner.Equal(1,a.AssistedColdEntryCount,"Entry count.");TestRunner.Equal(0,a.AssistedColdWritableEntries,"Writable entry.");TestRunner.True(a.MaximumNativeLoadRequests==1&&a.MaximumNativeWriteRequests==null,"Quota representation.");});
 t.Run("F09 Manual keeps the same one-load zero-write native authority",()=>{var f=new F(false,true);var a=f.Scope();TestRunner.True(a.MatchesAssistedColdInventoryPlan(f.R,f.Game,f.Manager),"F09 plan mismatch.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)==null,"F09 native load refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)!=null,"F09 second load admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Target,f.Root)!=null,"F09 write admitted.");Counts(a,1);});
 t.Run("third-Horse Manual 305 keeps one load and zero writes",()=>{var f=new F(false,false,false,true);var a=f.Scope();TestRunner.True(a.MatchesAssistedColdInventoryPlan(f.R,f.Game,f.Manager),"Third-Horse plan mismatch.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)==null,"Third-Horse native load refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)!=null,"Third-Horse second load admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Target,f.Root)!=null,"Third-Horse write admitted.");Counts(a,1);});
 t.Run("fourth-Horse Manual 306 keeps one load and zero writes",()=>{var f=new F(false,false,false,false,true);var a=f.Scope();TestRunner.True(a.MatchesAssistedColdInventoryPlan(f.R,f.Game,f.Manager),"Fourth-Horse plan mismatch.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)==null,"Fourth-Horse native load refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)!=null,"Fourth-Horse second load admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Target,f.Root)!=null,"Fourth-Horse write admitted.");Counts(a,1);});
 t.Run("fifth-Horse Manual 307 keeps one load and zero writes",()=>{var f=new F(false,false,false,false,false,false,true);var a=f.Scope();TestRunner.True(a.MatchesAssistedColdInventoryPlan(f.R,f.Game,f.Manager),"Fifth-Horse plan mismatch.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)==null,"Fifth-Horse native load refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)!=null,"Fifth-Horse second load admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Target,f.Root)!=null,"Fifth-Horse write admitted.");Counts(a,1);});
 t.Run("fifth-Horse authority refuses another Manual leaf",()=>{var f=new F(false,false,false,false,false,false,true);f.R.PersistenceLoad.FileName="Manual_308_KMC_C7_MANUAL_DERIVED_FIELD.zks";Refuse(()=>f.Scope());});
 t.Run("opened fourth-Horse selector admits the same exact Manual once and no write",()=>{var f=new F(false,false,false,false,false,true);var a=f.Scope();TestRunner.True(a.MatchesAssistedColdInventoryPlan(f.R,f.Game,f.Manager),"Selector plan mismatch.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)==null,"Selector Manual load refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Target,f.Root)!=null,"Selector write admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)!=null,"Selector second load admitted.");Counts(a,1);});
 t.Run("opened fourth-Horse selector refuses another Manual leaf before load",()=>{var f=new F(false,false,false,false,false,true);f.R.PersistenceLoad.FileName="Manual_307_KMC_C7_FOUR_HORSE_WORLD.zks";Refuse(()=>f.Scope());});
 t.Run("fourth-Horse authority refuses another Manual leaf",()=>{var f=new F(false,false,false,false,true);f.R.PersistenceLoad.FileName="Manual_307_KMC_C7_FOUR_HORSE_WORLD.zks";Refuse(()=>f.Scope());});
 t.Run("third-Horse authority refuses another Manual leaf",()=>{var f=new F(false,false,false,true);f.R.PersistenceLoad.FileName="Manual_306_KMC_C7_SMALL_WORLD.zks";Refuse(()=>f.Scope());});
 t.Run("paid Medium Manual keeps one load and no write",()=>{var f=new F(false,false,true);var a=f.Scope();TestRunner.True(a.MatchesAssistedColdInventoryPlan(f.R,f.Game,f.Manager),"Medium plan mismatch.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)==null,"Medium native load refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)!=null,"Medium second load admitted.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Write,f.Target,f.Root)!=null,"Medium write admitted.");Counts(a,1);});
 t.Run("one native load and non-consuming identity reads",()=>{var f=new F();var a=f.Scope();a.AssertReadableArchive(f.Target.FullPath);TestRunner.True(a.ValidateArchiveIdentity(f.Target,f.Root)==null&&a.Validate(RuntimeSaveOperation.Load,f.Target,f.Root)==null,"Preflight refused.");Counts(a,0);TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)==null,"Sole load refused.");a.AssertReadableArchive(f.Target.FullPath);TestRunner.True(a.ValidateArchiveIdentity(f.Target,f.Root)==null,"Post-load read refused.");TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)!=null,"Duplicate admitted.");Counts(a,1);});
 foreach(var op in new[]{RuntimeSaveOperation.Write,RuntimeSaveOperation.Delete})t.Run("nonload refuses "+op,()=>{var f=new F();var a=f.Scope();TestRunner.True(a.AuthorizeNativeRequest(op,f.Target,f.Root)!=null,"Nonload admitted.");Counts(a,0);});
 foreach(var boundary in new[]{"storage","replacement","delete"})t.Run("no writable boundary "+boundary,()=>{var f=new F();var a=f.Scope();Refuse(()=>{if(boundary=="storage")a.BeginWrite(f.Target,f.Root);if(boundary=="replacement")a.BeginReplacement(f.Target.FullPath,f.Target.FullPath);if(boundary=="delete")a.DeleteCompletedStaging(f.Target.FullPath);if(boundary=="projection")a.ProjectNewRequest(f.Target,f.Root);});Counts(a,0);TestRunner.True(V.Files[f.R.PersistenceLoad.FileName]==new string('c',64),"Source changed.");});
 foreach(var kind in new[]{"request","game","manager"})t.Run("foreign reference owner "+kind,()=>{var f=new F();var a=f.Scope();TestRunner.True(!a.MatchesAssistedColdInventoryPlan(kind=="request"?AssistedColdFixture.Request():f.R,kind=="game"?new object():f.Game,kind=="manager"?new object():f.Manager),"Foreign context matched.");Counts(a,0);});
 foreach(var kind in new[]{"duplicate","null-game","null-manager","wrong-load-cap","writable","write-cap","second-entry","foreign-campaign","foreign-area","wrong-hash","already-loaded"})t.Run("configuration refuses "+kind,()=>{var f=new F();var a=f.Scope(false,kind);if(kind=="duplicate")a.ConfigureAssistedColdInventory(f.R,f.Game,f.Manager);if(kind=="already-loaded")TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)==null,"Setup load.");Refuse(()=>a.ConfigureAssistedColdInventory(f.R,kind=="null-game"?null:f.Game,kind=="null-manager"?null:f.Manager));Counts(a,kind=="already-loaded"?1:0);});
 foreach(var kind in new[]{"path","leaf","name","type","campaign","game-name","area","root","hash","missing"})t.Run("exact native descriptor "+kind,()=>{var f=new F();var a=f.Scope();var x=f.Target;var root=f.Root;switch(kind){case"path":x.FullPath=Path.Combine(f.Root,"sub",x.FileName);break;case"leaf":x.FileName="Auto_1.zks";break;case"name":x.InternalName="KMC_AUTOMATION_WORKING";break;case"type":x.SaveType="Auto";break;case"campaign":x.GameId=AssistedColdFixture.Anchor;break;case"game-name":x.GameName="Other";break;case"area":x.Area=new string('e',32);break;case"root":root=Path.Combine(f.Root,"other");break;case"hash":V.Files[x.FileName]=new string('e',64);break;case"missing":V.Files.Clear();break;}TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,x,root)!=null,"Bad descriptor admitted.");Counts(a,0);});
 foreach(var field in new[]{"token","source-run","suite","source-length","source-ticks","baseline-length"})foreach(var boundary in new[]{"load","identity","readable","projection"})t.Run("captured mutation "+field+" at "+boundary,()=>{var f=new F();var a=f.Scope();switch(field){case"token":f.R.TransactionToken=new string('e',64);break;case"source-run":f.R.AssistedColdInventory.SourceRunId="other-source";break;case"suite":f.R.QualificationSuite.SuiteId="other-suite";break;case"source-length":f.R.PersistenceLoad.Length++;break;case"source-ticks":f.R.PersistenceLoad.LastWriteTimeUtcTicks++;break;case"baseline-length":f.R.Fixture.Baseline.Length++;break;}if(boundary=="load")TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)!=null,"Mutation load.");if(boundary=="identity")TestRunner.True(a.ValidateArchiveIdentity(f.Target,f.Root)!=null,"Mutation identity.");if(boundary=="readable")Refuse(()=>a.AssertReadableArchive(f.Target.FullPath));if(boundary=="projection")Refuse(()=>a.ProjectNewRequest(f.Target,f.Root));Counts(a,0);});
 t.Run("read-only projection grants no write target",()=>{var f=new F();var a=f.Scope();var predicted=f.Target;TestRunner.True(ReferenceEquals(predicted,a.ProjectNewRequest(predicted,f.Root)),"Read-only scope projected a writable leaf.");TestRunner.True(a.Validate(RuntimeSaveOperation.Write,predicted,f.Root)!=null,"Projection authorized writing.");Counts(a,0);});
 t.Run("post-load captured mutation refuses reads",()=>{var f=new F();var a=f.Scope();TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)==null,"Setup load.");f.R.AssistedColdInventory.SourceArtifactSha256=new string('f',64);Refuse(()=>a.AssertReadableArchive(f.Target.FullPath));TestRunner.True(!a.MatchesAssistedColdInventoryPlan(f.R,f.Game,f.Manager),"Mutated match.");Counts(a,1);});
 ShapeChecks(t);
 foreach(var group in Targets(new F()).Keys.ToArray())foreach(var property in Targets(new F())[group].GetType().GetProperties().Where(p=>p.CanRead&&p.CanWrite&&(p.PropertyType==typeof(string)||p.PropertyType==typeof(int)||p.PropertyType==typeof(long)||p.PropertyType==typeof(bool)||p.PropertyType==typeof(bool?)))){var g=group;var p=property;t.Run("every admitted scalar "+g+"."+p.Name,()=>{var f=new F();var a=f.Scope();var target=Targets(f)[g];var before=p.GetValue(target);object after=p.PropertyType==typeof(string)?(object)((string)before+"|changed:;\n"):p.PropertyType==typeof(int)?(object)((int)before+1):p.PropertyType==typeof(long)?(object)((long)before+1):p.PropertyType==typeof(bool)?(object)!(bool)before:(object)(bool?)true;p.SetValue(target,after);TestRunner.True(!a.MatchesAssistedColdInventoryPlan(f.R,f.Game,f.Manager),"Ignored scalar.");Refuse(()=>a.AssertReadableArchive(f.Target.FullPath));Counts(a,0);});}
 foreach(var property in typeof(RuntimeRequest).GetProperties().Where(p=>p.CanRead&&p.CanWrite&&!p.PropertyType.IsValueType&&p.PropertyType!=typeof(string)&&p.Name!="Fixture"&&p.Name!="QualificationSuite"&&p.Name!="PersistenceLoad"&&p.Name!="AssistedColdInventory")){var p=property;t.Run("foreign selection "+p.Name,()=>{var f=new F();var a=f.Scope();p.SetValue(f.R,p.PropertyType.IsArray?Array.CreateInstance(p.PropertyType.GetElementType(),0):Activator.CreateInstance(p.PropertyType));TestRunner.True(!a.MatchesAssistedColdInventoryPlan(f.R,f.Game,f.Manager),"Ignored foreign object.");Refuse(()=>a.AssertReadableArchive(f.Target.FullPath));Counts(a,0);});}
 t.Run("null empty scalar distinct",()=>{var f=new F();var a=f.Scope();f.R.SaveName="";TestRunner.True(!a.MatchesAssistedColdInventoryPlan(f.R,f.Game,f.Manager),"Null empty collapsed.");});
 t.Run("historical unconfigured read-only scope unchanged",()=>{var f=new F();var a=f.Scope(false);TestRunner.True(a.AuthorizeNativeRequest(RuntimeSaveOperation.Load,f.Target,f.Root)==null,"Legacy load.");a.AssertReadableArchive(f.Target.FullPath);Counts(a,1);});
 return t.Complete();}
 static Dictionary<string,object> Targets(F f)=>new Dictionary<string,object>{{"request",f.R},{"baseline",f.R.Fixture.Baseline},{"working",f.R.Fixture.Working},{"source",f.R.PersistenceLoad},{"write",f.R.Fixture.WriteAuthorization},{"suite",f.R.QualificationSuite},{"cold",f.R.AssistedColdInventory}};
 static void Counts(PersistenceSaveAuthorization a,int loads){TestRunner.Equal(loads,a.AdmittedNativeLoadRequests,"Load count.");TestRunner.Equal(0,a.AdmittedNativeWriteRequests,"Write count.");}
 static void Refuse(Action action){var refused=false;try{action();}catch(InvalidOperationException){refused=true;}catch(IOException){refused=true;}catch(ArgumentException){refused=true;}TestRunner.True(refused,"Expected refusal.");}
 static string Shape(Type type)=>string.Join("|",type.GetProperties(BindingFlags.Public|BindingFlags.Instance).Where(p=>p.CanRead&&p.CanWrite).Select(p=>p.Name+":"+(Nullable.GetUnderlyingType(p.PropertyType)==null?p.PropertyType.Name:"Nullable<"+Nullable.GetUnderlyingType(p.PropertyType).Name+">")).OrderBy(x=>x,StringComparer.Ordinal));
 static void ShapeChecks(TestRunner t){
  t.Run("exact admitted DTO RuntimeRequest",()=>TestRunner.Equal("AcquiredManual:Chunk7AcquiredManualSelection|AssistedColdInventory:Chunk7AssistedColdInventorySelection|AssistedFixture:Chunk7AssistedFixtureSelection|BootstrapInventory:Chunk7BootstrapInventorySelection|Branch:String|Commit:String|CumulativeAcquisition:Chunk7CumulativeAcquisitionSelection|DllMvid:String|DllSha256:String|EvidenceRoot:String|F11AllocationProbe:F11NativeAllocationSelection|Fixture:RuntimeFixtureIdentity|LoadRefusalDerivationSha256:String|ManualDerived:Chunk7ManualDerivedSelection|ManualSeed:Chunk7ManualSeedSelection|NativeBootstrap:Chunk7NativeBootstrapSelection|ObserveWorkingDeserialization:Nullable<Boolean>|OrdinaryAcquisition:Chunk7OrdinaryAcquisitionSelection|OrdinaryField:Chunk7OrdinaryFieldSelection|OwnedPairs:Chunk7OwnedPairsSelection|OwnerStockRemoval:Nullable<Boolean>|PersistenceAlternate:RuntimeSaveDescriptor|PersistenceAreaTarget:RuntimeAreaTransitionTarget|PersistenceCase:String|PersistenceLoad:RuntimeSaveDescriptor|PersistenceReplayTargets:RuntimeAreaTransitionTarget[]|ProductVersion:String|Progression:Chunk7ProgressionSelection|QualificationSuite:RuntimeQualificationSuiteIdentity|RunId:String|SaveAccessAllowed:Boolean|SaveName:String|Scenario:String|Schema1DerivationSha256:String|Schema2DerivationSha256:String|SchemaVersion:Int32|SmallCalibration:Chunk7SmallCalibrationSelection|SmallFixture:Chunk7SmallFixtureSelection|StockMammothFixture:Chunk7StockMammothFixtureSelection|TransactionToken:String",Shape(typeof(RuntimeRequest)),"Review new DTO property coverage."));
  t.Run("exact admitted DTO RuntimeFixtureIdentity",()=>TestRunner.Equal("Baseline:RuntimeSaveDescriptor|Working:RuntimeSaveDescriptor|WriteAuthorization:RuntimeSaveWriteAuthorization",Shape(typeof(RuntimeFixtureIdentity)),"Review new DTO property coverage."));
  t.Run("exact admitted DTO RuntimeSaveDescriptor",()=>TestRunner.Equal("Area:String|FileName:String|GameId:String|GameName:String|InternalName:String|LastWriteTimeUtcTicks:Int64|Length:Int64|Sha256:String",Shape(typeof(RuntimeSaveDescriptor)),"Review new DTO property coverage."));
  t.Run("exact admitted DTO RuntimeSaveWriteAuthorization",()=>TestRunner.Equal("AllowedFileName:String|AllowedInternalName:String|BaselineImmutable:Boolean|Mode:String",Shape(typeof(RuntimeSaveWriteAuthorization)),"Review new DTO property coverage."));
  t.Run("exact admitted DTO RuntimeQualificationSuiteIdentity",()=>TestRunner.Equal("SnapshotSha256:String|SuiteId:String",Shape(typeof(RuntimeQualificationSuiteIdentity)),"Review new DTO property coverage."));
  t.Run("exact admitted DTO Chunk7AssistedColdInventorySelection",()=>TestRunner.Equal("BaseGameOnly:Boolean|Case:String|ExpectedNativeLoadCount:Int32|ExpectedNativeWriteCount:Int32|SeedId:String|SeedSha256:String|SourceArchiveSha256:String|SourceArtifactSha256:String|SourceRunId:String",Shape(typeof(Chunk7AssistedColdInventorySelection)),"Review new DTO property coverage."));
 }
 sealed class F{
 internal readonly object Game=new object(),Manager=new object();internal readonly RuntimeRequest R;internal string Root=@"C:\KmcBootstrapVirtual\run\Saved Games";
 internal F(bool seed=false,bool small=false,bool medium=false,bool thirdHorse=false,bool fourthHorse=false,bool selector=false,bool fifthHorse=false,bool departure=false,bool sixthHorse=false){R=sixthHorse?AssistedColdFixture.SixthHorseRequest():departure?AssistedColdFixture.FifthHorseDepartureRequest():seed?AssistedColdFixture.SeedRequest():fifthHorse?AssistedColdFixture.FifthHorseRequest():selector?AssistedColdFixture.FourthHorseSelectorRequest():fourthHorse?AssistedColdFixture.FourthHorseRequest():thirdHorse?AssistedColdFixture.ThirdHorseRequest():medium?AssistedColdFixture.MediumRequest():small?AssistedColdFixture.SmallRequest():AssistedColdFixture.Request();V.Files.Clear();V.Throw=false;V.Files[R.PersistenceLoad.FileName]=R.PersistenceLoad.Sha256;}
 internal RuntimeSaveTarget Target=>new RuntimeSaveTarget{FileName=R.PersistenceLoad.FileName,InternalName=R.PersistenceLoad.InternalName,FullPath=Path.Combine(Root,R.PersistenceLoad.FileName),SaveType="Manual",GameId=R.PersistenceLoad.GameId,GameName=R.PersistenceLoad.GameName,Area=R.PersistenceLoad.Area};
 internal PersistenceSaveAuthorization Scope(bool configure=true,string kind=null){var entries=new List<PersistenceSaveEntry>{new PersistenceSaveEntry{FileName=R.PersistenceLoad.FileName,InternalName=R.PersistenceLoad.InternalName,SaveType="Manual",Area=kind=="foreign-area"?new string('e',32):R.PersistenceLoad.Area,InitialSha256=kind=="wrong-hash"?new string('e',64):R.PersistenceLoad.Sha256,Writable=kind=="writable"}};if(kind=="second-entry")entries.Add(new PersistenceSaveEntry{FileName="Manual_8_KMC_C7_ASSISTED_FIXTURE.zks",InternalName=R.PersistenceLoad.InternalName,SaveType="Manual",Area=R.PersistenceLoad.Area});if(kind=="wrong-hash")V.Files[R.PersistenceLoad.FileName]=new string('e',64);var a=new PersistenceSaveAuthorization(@"C:\KmcBootstrapVirtual\run",kind=="foreign-campaign"?AssistedColdFixture.Anchor:R.PersistenceLoad.GameId,R.PersistenceLoad.GameName,R.Fixture.Baseline.Sha256,entries,null,null,kind=="write-cap"?(int?)1:null,kind=="wrong-load-cap"?2:1);if(configure)a.ConfigureAssistedColdInventory(R,Game,Manager);return a;}
 }
